    <section class="library-stats"><div class="library-stat primary"><span>待你确认</span><strong>{{ summary.recommendation_count || 0 }}</strong><small>系统按近期错题自动整理</small></div><div class="library-stat"><span>已沉淀考法</span><strong>{{ summary.type_count || 0 }}</strong><small>覆盖 {{ summary.knowledge_count || 0 }} 个知识点</small></div><div class="library-stat"><span>本周维护</span><strong>{{ summary.updated_this_week || 0 }}</strong><small>题型自带独立内容快照</small></div></section>
    <ContentCard class="automation-guide" flush><div class="guide-copy"><span class="guide-step">1</span><div><strong>先看系统整理</strong><small>基于近期错题的主知识点、错误人数和典型代表题自动分组。</small></div></div><div class="guide-copy"><span class="guide-step">2</span><div><strong>确认值得讲的考法</strong><small>保留、编辑或忽略；不会修改任何学生的错题和掌握度。</small></div></div><div class="guide-copy"><span class="guide-step">3</span><div><strong>确认后沉淀为考法库</strong><small>按“知识点 → 考法 → 代表题”组织，讲法与易错点长期可复用。</small></div></div></ContentCard>
    <FilterBar class="type-filter"><template #leading><div class="result-context"><strong>{{ activeMode === 'recommended' ? '本周自动整理' : (activeMode === 'knowledge' ? '按考点选题' : '已确认考法库') }}</strong><span>{{ types.length }} 个题型</span></div></template><el-button-group><el-button :type="activeMode === 'recommended' ? 'primary' : ''" @click="setMode('recommended')">待确认</el-button><el-button :type="activeMode === 'library' ? 'primary' : ''" @click="setMode('library')">已确认</el-button><el-button :type="activeMode === 'knowledge' ? 'primary' : ''" @click="setMode('knowledge')">按考点选题</el-button></el-button-group><WorkbenchInput v-model="keyword" clearable placeholder="搜索考法或讲法" width="240px" aria-label="搜索考法或讲法" @input="debouncedLoad"><template #prefix><el-icon><Search /></el-icon></template></WorkbenchInput><WorkbenchSelect v-model="selectedKpId" :options="kpFilterOptions" :filterable="true" clearable placeholder="全部知识点" width="200px" aria-label="按知识点筛选" @change="activeMode==='knowledge'?loadKpQuestions():loadTypes()" /><el-checkbox v-if="activeMode==='knowledge'" v-model="onlyWrong" @change="loadKpQuestions">只看有人错过的题</el-checkbox><template #actions><el-button v-if="activeMode!=='knowledge'" text @click="startCreate"><el-icon><Plus /></el-icon>手动补充</el-button></template></FilterBar>
    <main v-if="activeMode==='knowledge'" class="library-workspace"><ContentCard class="type-list-card cooccur-card" :title="`${activeKpName||'考点'} · 常一起错的考点`" :description="cooccurSummaryText" flush><div v-if="cooccurLoading" class="list-loading"><el-skeleton animated :rows="3" /></div><EmptyState v-else-if="!cooccurNodes.length" :icon="Share" title="先选一个考点" description="选一个考点后，这里展开它和共现最强的 8 个邻居——点邻居可直接切过去。" compact /><div v-else class="cooccur-body"><VChart class="cooccur-chart" :option="cooccurOption" autoresize @click="onCooccurClick" /><div class="cooccur-peers"><button v-for="n in cooccurPeers" :key="n.id" type="button" :class="['cooccur-peer',{inScope:n.in_scope}]" @click="jumpToKp(n.id)"><strong>{{ n.name }}</strong><small>共现 {{ n.cooccur }} 道题<template v-if="n.own_count"> · 自身 {{ n.own_count }}</template></small></button><p v-if="!cooccurPeers.length" class="cooccur-empty">这个考点还没跟别的考点在同一道题里出现过。</p></div></div></ContentCard><ContentCard class="type-list-card" :title="`${activeKpName||'考点'} · 题目清单`" :description="kpSummaryText" flush><div v-if="kpLoading" class="list-loading"><el-skeleton v-for="index in 6" :key="index" animated :rows="2" /></div><EmptyState v-else-if="!kpQuestions.length" :icon="Collection" title="先选一个考点" description="用上方「全部知识点」下拉挑一个考点，会拉出它挂的全部题目（含子考点）。" compact /><div v-else class="type-list"><button v-for="q in kpQuestions" :key="q.questionId" type="button" :class="['type-row',{active:kpActiveId===q.questionId}]" @click="kpActiveId=q.questionId"><span class="row-main"><strong>{{ q.wrongCount ? `${q.wrongCount} 次错 · ${q.studentCount} 人` : '暂无错次' }}</strong><small>{{ (q.content||'(无题干)').replace(/\s+/g,' ').slice(0,80) }}</small></span><span class="row-evidence" v-if="q.students?.length">{{ q.students.slice(0,3).join('、') }}{{ q.students.length>3?` 等${q.students.length}人`:`` }}</span><el-icon><ArrowRight /></el-icon></button></div></ContentCard><ContentCard class="type-inspector" title="题目详情" :description="activeKpQuestion ? (activeKpQuestion.kps||[]).map(k=>k.name).join(' · ') || '关联考点' : '选一道题查看'" flush><EmptyState v-if="!activeKpQuestion" :icon="Reading" title="选一道题" description="左侧点题目，这里显示完整题干、答案与关联考点。" compact /><article v-else class="type-detail"><div class="detail-heading"><div><div class="knowledge-label">{{ activeKpQuestion.subject || '数学' }} · {{ activeKpQuestion.difficulty ? `难度 ${activeKpQuestion.difficulty}` : '难度未判定' }}</div><h2>{{ activeKpQuestion.wrongCount ? `${activeKpQuestion.wrongCount} 次错 · ${activeKpQuestion.studentCount} 人` : '暂无错次' }}</h2></div></div><section class="detail-section"><h3>题干</h3><p class="kp-content">{{ activeKpQuestion.content || '题目内容不可用' }}</p></section><section class="detail-section" v-if="activeKpQuestion.options"><h3>选项</h3><p class="kp-content">{{ formatOptions(activeKpQuestion.options) }}</p></section><section class="detail-section" v-if="activeKpQuestion.answer"><h3>参考答案</h3><p class="kp-content">{{ activeKpQuestion.answer }}</p></section><section class="detail-section" v-if="activeKpQuestion.students?.length"><h3>错过的学生</h3><p>{{ activeKpQuestion.students.join('、') }}</p></section><div class="kp-actions"><ActionButton variant="primary" :disabled="!selectedKpId" @click="sendKpToWeekend"><el-icon><Promotion /></el-icon>按「{{ activeKpName }}」进入周末班课件</ActionButton></div></article></ContentCard></main><main v-else class="library-workspace"><ContentCard class="type-list-card" title="考法清单" :description="activeMode === 'recommended' ? '优先确认近期高频、多人出错的考法' : '长期可复用的教学考法'" flush><div v-if="loading" class="list-loading"><el-skeleton v-for="index in 6" :key="index" animated :rows="2" /></div><EmptyState v-else-if="!types.length" :icon="activeMode === 'recommended' ? CircleCheck : Collection" :title="activeMode === 'recommended' ? '本周没有待确认考法' : '还没有已确认考法'" :description="activeMode === 'recommended' ? '可以更新本周整理，或近期错题尚未完成知识点关联。' : '先确认系统整理的考法，或手动补充一个教学考法。'"><template #actions><ActionButton v-if="activeMode === 'recommended'" @click="autoOrganize">更新本周整理</ActionButton><ActionButton v-else variant="primary" @click="startCreate">手动补充考法</ActionButton></template></EmptyState><div v-else class="type-list"><button v-for="item in types" :key="item.id" type="button" :class="['type-row',{active:selectedId===item.id}]" @click="selectType(item.id)"><span class="row-main"><strong>{{ item.name }}</strong><small>{{ item.knowledge_name }} · {{ item.example_count }} 道代表题</small></span><span class="row-evidence" v-if="item.auto_summary?.wrongCount">{{ item.auto_summary.wrongCount }} 次错误<br>{{ item.auto_summary.studentCount }} 名学生</span><el-icon><ArrowRight /></el-icon></button></div></ContentCard>
      <ContentCard class="type-inspector" title="考法详情" :description="selectedType ? `${selectedType.knowledge_name} · ${selectedType.status === 'draft' ? '系统建议，等待确认' : '已确认教学资产'}` : '选择一个题型查看详情'" flush><div v-if="detailLoading" class="detail-loading"><el-skeleton animated :rows="10" /></div><EmptyState v-else-if="!selectedType" :icon="Reading" title="选择一个题型" description="右侧会展示系统依据、讲解建议和代表题。" compact /><article v-else class="type-detail"><div class="detail-heading"><div><div class="knowledge-label">{{ selectedType.knowledge_name }}</div><h2>{{ selectedType.name }}</h2></div><el-dropdown @command="handleDetailAction"><el-button text aria-label="考法操作"><el-icon><MoreFilled /></el-icon></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="edit">编辑考法</el-dropdown-item><el-dropdown-item command="ignore" v-if="selectedType.status==='draft'" divided>忽略本次建议</el-dropdown-item><el-dropdown-item command="archive" v-else divided>归档题型</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div><div class="recommendation" v-if="selectedType.status==='draft'"><strong>系统建议</strong><span>近 {{ selectedType.auto_summary?.days || 14 }} 天内，{{ selectedType.auto_summary?.studentCount || 0 }} 名学生出现 {{ selectedType.auto_summary?.wrongCount || 0 }} 次相关错误。</span></div><div v-if="selectedType.tags?.length" class="detail-tags"><el-tag v-for="tag in selectedType.tags" :key="tag" size="small">{{tag}}</el-tag></div><section class="detail-section"><h3>建议课堂讲法</h3><p>{{selectedType.teaching_notes || '暂未生成讲法。'}}</p></section><section class="detail-section"><h3>典型易错点</h3><p>{{selectedType.common_mistakes || '暂未收集到明确错因。'}}</p></section><section class="detail-section examples"><div class="section-heading"><h3>代表题</h3><span>{{selectedType.examples?.length || 0}} 道</span></div><article v-for="example in selectedType.examples" :key="example.id" class="example-card"><div class="example-content">{{example.snapshot?.content || '题目内容快照不可用'}}</div><div class="example-meta"><span>{{example.snapshot?.questionType || '综合题'}}</span><span v-if="example.snapshot?.answer">答案：{{example.snapshot.answer}}</span></div><el-button v-if="example.sourceQuestionId" text size="small" :loading="variantLoadingId===example.id" @click="generateVariants(example)">生成变式练习</el-button></article></section><div class="detail-actions" v-if="selectedType.status==='draft'"><el-button @click="editSelected">先修改</el-button><el-button type="primary" :loading="confirming" @click="confirmType">确认收录到题型库</el-button></div></article></ContentCard></main>
  </div>
  <el-drawer v-model="editorVisible" :title="editingId ? '编辑考法' : '手动补充考法'" size="min(520px,100%)" destroy-on-close><el-form label-position="top" :model="editor"><el-form-item label="主知识点" required><WorkbenchSelect v-model="editor.kpId" :options="editorKpOptions" :filterable="true" placeholder="选择主知识点" aria-label="选择主知识点" /></el-form-item><el-form-item label="题型名称" required><WorkbenchInput v-model="editor.name" :maxlength="60" show-word-limit placeholder="如：相似三角形判定" aria-label="题型名称" /></el-form-item><el-form-item label="课堂讲法"><WorkbenchInput v-model="editor.teachingNotes" type="textarea" :rows="5" placeholder="记录课堂讲法，便于复用" aria-label="课堂讲法" /></el-form-item><el-form-item label="易错提醒"><WorkbenchInput v-model="editor.commonMistakes" type="textarea" :rows="3" placeholder="学生常见错误与应对" aria-label="易错提醒" /></el-form-item><el-form-item label="教学标签"><el-select v-model="editor.tags" multiple filterable allow-create class="wb-select" style="width:100%" placeholder="输入后回车添加" aria-label="教学标签" /></el-form-item></el-form><template #footer><div class="drawer-actions"><el-button @click="editorVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveType">保存</el-button></div></template></el-drawer>
  </div>
</template>
<script setup>
import {computed,onMounted,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {ArrowRight,CircleCheck,Collection,MoreFilled,Plus,Promotion,Reading,Refresh,Search,Share} from '@element-plus/icons-vue'
// 聚焦网状图用 echarts graph 力导向布局 —— echarts 6.1.0 + vue-echarts 8.0.1 已在依赖里
// （工作台 DashboardWorkbench / TrendLineChart 已在用），不需要新装包。
import {use} from 'echarts/core'
import {GraphChart} from 'echarts/charts'
import {TooltipComponent} from 'echarts/components'
import {CanvasRenderer} from 'echarts/renderers'
import VChart from 'vue-echarts'
import {apiRequest,getKnowledgeTree} from '../../services/apiService'
use([GraphChart,TooltipComponent,CanvasRenderer])
import ActionButton from '../components/ui/ActionButton.vue'; import ContentCard from '../components/ui/ContentCard.vue'; import EmptyState from '../components/ui/EmptyState.vue'; import FilterBar from '../components/ui/FilterBar.vue'; import PageHeader from '../components/ui/PageHeader.vue'; import WorkbenchInput from '../components/ui/WorkbenchInput.vue'; import WorkbenchSelect from '../components/ui/WorkbenchSelect.vue'
const route=useRoute(), router=useRouter(), types=ref([]),summary=ref({}),tree=ref([]),activeMode=ref('recommended'),selectedKpId=ref(''),keyword=ref(''),selectedId=ref(null),selectedType=ref(null),onlyWrong=ref(false),loading=ref(false),detailLoading=ref(false),organizing=ref(false),confirming=ref(false),saving=ref(false),variantLoadingId=ref(null),editorVisible=ref(false),editingId=ref(null),kpQuestions=ref([]),kpLoading=ref(false),kpActiveId=ref(null),kpScope=ref(null),cooccurNodes=ref([]),cooccurLoading=ref(false)
const blankEditor=()=>({kpId:selectedKpId.value||'',name:'',teachingNotes:'',commonMistakes:'',tags:[]}); const editor=ref(blankEditor()); const flatten=(nodes,out=[])=>{for(const node of nodes||[]){out.push(node);flatten(node.children,out)}return out}; const flatKnowledge=computed(()=>flatten(tree.value)); const kpFilterOptions=computed(()=>[{label:'全部知识点',value:''},...flatKnowledge.value.map(kp=>({label:'　'.repeat(kp.level||0)+kp.name,value:kp.id}))]); const editorKpOptions=computed(()=>flatKnowledge.value.map(kp=>({label:'　'.repeat(kp.level||0)+kp.name,value:kp.id}))); let timer; const debouncedLoad=()=>{clearTimeout(timer);timer=setTimeout(loadTypes,250)}
async function loadTypes(){loading.value=true;try{const params=new URLSearchParams({mode:activeMode.value});if(selectedKpId.value)params.set('kpId',selectedKpId.value);if(keyword.value)params.set('keyword',keyword.value);const data=await apiRequest(`/teaching-question-types?${params}`);types.value=data.types||[];if(selectedId.value&&!types.value.some(item=>item.id===selectedId.value)){selectedId.value=null;selectedType.value=null}}catch(error){ElMessage.error(error.message||'加载考法失败')}finally{loading.value=false}}const activeKpQuestion=computed(()=>kpQuestions.value.find(q=>q.questionId===kpActiveId.value)||null)
const activeKpName=computed(()=>{const hit=flatKnowledge.value.find(k=>k.id===selectedKpId.value);return hit?hit.name:''})
const kpSummaryText=computed(()=>{if(!selectedKpId.value)return '先选一个考点';const s=kpScope.value;return `${s?`含子考点共 ${s.expandedNodes} 个节点 · `:''}拉到 ${kpQuestions.value.length} 道题`})
// ── 聚焦网状图（P1）─────────────────────────────────────────────
// 为什么是「聚焦 9 个点」而不是整张网：全量共现 1553 边 / 294 节点，摊开是毛线球。
// 每个邻居都从当前考点连出来、且带真实共现题数 ⇒ 每条边都回答得了「为什么该连它」。
const COOCUR_LIMIT=8
const cooccurLinks=ref([])
const cooccurPeers=computed(()=>cooccurNodes.value.filter(n=>!n.is_center))
const cooccurSummaryText=computed(()=>{if(!selectedKpId.value)return '选一个考点展开它的共现邻居';const peers=cooccurPeers.value;if(!peers.length)return '暂无可展开的邻居';return `${activeKpName.value} 自身 ${cooccurNodes.value.find(n=>n.is_center)?.own_count||0} 题 · 与 ${peers.length} 个考点同题共现`})
// 节点大小按共现强度开方缩放（线性会让332 的一根柱子把其余全压成看不见）
// ⛔ r145 实测修：中心原本**硬编码 34**，邻居走 `12+26*√(w/maxW)`，上限 38。
//   平方根自身 353 题、邻居「平方」共现也是 353 ⇒ 邻居半径 38.0 > 中心 34，
//   视觉上「我选中的考点」反而比它最强的邻居小，主次颠倒。
//   修法：中心也走同一套公式（own_count 参与 maxW），再乘 1.2 系数 + 半径下限 30。
//   实测平方根：中心 46 / 最大邻居「平方」38 ⇒ 主次恢复正常（1.2 是在 1.15~1.25 之间
//   试出来的：太小会被压住，太大在 repulsion=340 的布局里显得孤立）。
const cooccurOption=computed(()=>{const nodes=cooccurNodes.value;if(!nodes.length)return {};const weightOf=n=>Math.max(Number(n.is_center?n.own_count:n.cooccur)||0,0);const maxW=Math.max(...nodes.map(weightOf),1);const radius=n=>{const base=12+26*Math.sqrt(weightOf(n)/maxW);return n.is_center?Math.max(Math.round(base*1.2),30):base};return{animationDuration:420,tooltip:{trigger:'item',formatter:p=>p.data?.raw||p.name},series:[{type:'graph',layout:'force',roam:false,draggable:true,force:{repulsion:340,edgeLength:[70,150],gravity:0.12},label:{show:true,position:'bottom',fontSize:11,color:'var(--wb-text-secondary)',formatter:p=>p.name},labelLayout:{hideOverlap:true},lineStyle:{color:'#b4b2a9',width:1,curveness:0.12,opacity:0.7},emphasis:{focus:'adjacency',lineStyle:{width:2.5}},data:nodes.map(n=>({id:n.id,name:n.name,raw:`${n.name}｜共现 ${n.cooccur} 道题｜自身 ${n.own_count} 题`,symbolSize:radius(n),itemStyle:n.is_center?{color:'#7f77dd',borderColor:'#3c3489',borderWidth:1}:{color:n.in_scope?'#afa9ec':'#d3d1c7',borderColor:'#888780',borderWidth:0.5},label:{color:n.is_center?'#3c3489':'var(--wb-text-secondary)',fontWeight:n.is_center?600:400}})),links:cooccurLinks.value.map(l=>({...l,lineStyle:{width:1+2*Math.sqrt(l.value/Math.max(...cooccurLinks.value.map(x=>x.value),1))}}))}]}})
// 图上点节点 = 切考点。整页只有这一个出口，不新增页面。
function onCooccurClick(params){const hit=cooccurNodes.value.find(n=>n.id===params?.data?.id||n.name===params?.name);if(hit&&!hit.is_center)jumpToKp(hit.id)}
// ⛔ 只走 loadKpQuestions —— 它的 finally 里已经串了 loadCooccur，这里再调一次会打两次接口
function jumpToKp(id){if(!id)return;selectedKpId.value=id;loadKpQuestions()}
async function loadCooccur(){if(!selectedKpId.value){cooccurNodes.value=[];cooccurLinks.value=[];return}cooccurLoading.value=true;try{const p=new URLSearchParams({kpId:selectedKpId.value,limit:String(COOCUR_LIMIT)});const data=await apiRequest(`/teaching-question-types/kp-cooccur?${p}`);cooccurNodes.value=data.graph?.nodes||[];cooccurLinks.value=data.graph?.links||[]}catch(error){cooccurNodes.value=[];cooccurLinks.value=[];console.warn('共现图加载失败',error.message||error)}finally{cooccurLoading.value=false}}
function formatOptions(raw){if(!raw)return '';if(typeof raw==='string')return raw;try{const arr=Array.isArray(raw)?raw:JSON.parse(raw);return (arr||[]).map(o=>typeof o==='string'?o:(o.label||o.text||o.value||'')).filter(Boolean).join('  ')}catch(e){return String(raw)}}
async function loadKpQuestions(){if(!selectedKpId.value){kpQuestions.value=[];kpScope.value=null;return}kpLoading.value=true;kpActiveId.value=null;try{const p=new URLSearchParams({kpId:selectedKpId.value,includeChildren:'1',onlyWrong:onlyWrong.value?'1':'0',limit:'120'});const data=await apiRequest(`/teaching-question-types/kp-questions?${p}`);kpQuestions.value=data.questions||[];kpScope.value=data.scope||null;if(kpQuestions.value.length)kpActiveId.value=kpQuestions.value[0].questionId}catch(error){ElMessage.error(error.message||'加载考点题目失败')}finally{kpLoading.value=false;loadCooccur()}}
function sendKpToWeekend(){if(!selectedKpId.value)return ElMessage.warning('先选一个考点');router.push({path:'/weekend-ppt',query:{kpIds:selectedKpId.value}})}
async function loadSummary(){const data=await apiRequest('/teaching-question-types/summary');summary.value=data.summary||{}} async function selectType(id){selectedId.value=id;detailLoading.value=true;try{const data=await apiRequest(`/teaching-question-types/${id}`);selectedType.value=data.type}catch(error){ElMessage.error(error.message||'加载详情失败')}finally{detailLoading.value=false}} function setMode(mode){activeMode.value=mode;selectedId.value=null;selectedType.value=null;if(mode==='knowledge')return loadKpQuestions();loadTypes()}
async function autoOrganize(silent=false){organizing.value=true;try{const data=await apiRequest('/teaching-question-types/auto-organize',{method:'POST',body:JSON.stringify({days:14})});if(!silent)ElMessage.success(data.message||'本周整理已更新');activeMode.value='recommended';await Promise.all([loadTypes(),loadSummary()])}catch(error){const message=/404/.test(String(error.message))?'考法库后端尚未更新，请在 Render 重新部署最新 main 后重试':(error.message||'自动整理失败');if(!silent)ElMessage.error(message);else console.warn(message)}finally{organizing.value=false}}
async function confirmType(){confirming.value=true;try{await apiRequest(`/teaching-question-types/${selectedType.value.id}/confirm`,{method:'POST'});ElMessage.success('已收录到长期考法库');selectedType.value.status='active';await Promise.all([loadTypes(),loadSummary()])}catch(error){ElMessage.error(error.message||'确认失败')}finally{confirming.value=false}}
function startCreate(){editingId.value=null;editor.value=blankEditor();editorVisible.value=true} function editSelected(){editingId.value=selectedType.value.id;editor.value={kpId:selectedType.value.kp_id,name:selectedType.value.name,teachingNotes:selectedType.value.teaching_notes,commonMistakes:selectedType.value.common_mistakes,tags:selectedType.value.tags||[]};editorVisible.value=true} async function saveType(){if(!editor.value.kpId||!editor.value.name.trim())return ElMessage.warning('请填写主知识点和题型名称');saving.value=true;try{const payload={kpId:editor.value.kpId,name:editor.value.name,teachingNotes:editor.value.teachingNotes,commonMistakes:editor.value.commonMistakes,tags:editor.value.tags};const data=editingId.value?await apiRequest(`/teaching-question-types/${editingId.value}`,{method:'PUT',body:JSON.stringify(payload)}):await apiRequest('/teaching-question-types',{method:'POST',body:JSON.stringify(payload)});editorVisible.value=false;await Promise.all([loadTypes(),loadSummary()]);await selectType(data.type.id);ElMessage.success('考法已保存')}catch(error){ElMessage.error(error.message||'保存失败')}finally{saving.value=false}}
async function generateVariants(example){variantLoadingId.value=example.id;try{const response=await apiRequest(`/variants/${example.sourceQuestionId}/generate-all`,{method:'POST',body:JSON.stringify({})});ElMessage.success(response.generated?`已生成 ${response.generated} 道变式题`:'变式题已就绪')}catch(error){ElMessage.error(error.message||'生成变式题失败')}finally{variantLoadingId.value=null}} function handleDetailAction(command){if(command==='edit')return editSelected();const isIgnore=command==='ignore';ElMessageBox.confirm(isIgnore?'忽略后本次自动建议将不再展示。':'归档后考法不再参与自动整理与推荐。',isIgnore?'忽略建议':'归档考法',{type:'warning'}).then(async()=>{await apiRequest(`/teaching-question-types/${selectedType.value.id}${isIgnore?'/ignore':''}`,{method:isIgnore?'POST':'DELETE'});selectedId.value=null;selectedType.value=null;await Promise.all([loadTypes(),loadSummary()]);ElMessage.success(isIgnore?'已忽略本次建议':'考法已归档')}).catch(()=>{})}
onMounted(async()=>{
  // 支持从 Dashboard 薄弱知识点跳转：/question-bank?kpId=xxx 预筛
  const queryKpId = route.query.kpId;
  if (queryKpId) selectedKpId.value = String(queryKpId);
  // 支持从周末班课件「考点」回跳：/question-bank?kpId=xxx&mode=knowledge
  if (route.query.mode === 'knowledge') activeMode.value = 'knowledge';
  try{tree.value=await getKnowledgeTree('数学')}catch{ElMessage.warning('知识点目录加载失败')}
  await autoOrganize(true);
  await Promise.all([activeMode.value==='knowledge'?loadKpQuestions():loadTypes(),loadSummary()])
})
</script>
