ions{display:flex;justify-content:flex-end;gap:8px}@media(max-width:900px){.library-workspace{grid-template-columns:1fr}.type-list-card,.type-inspector{min-height:auto}.type-inspector{min-height:440px}}@media(max-width:720px){.library-stats,.automation-guide{grid-template-columns:1fr}.library-stat,.guide-copy{border-right:0;border-bottom:1px solid var(--wb-border-light)}.library-stat:last-child,.guide-copy:last-child{border-bottom:0}.type-filter :deep(.filter-bar__body){align-items:stretch;flex-direction:column}.row-evidence{display:none}}
